<template>
  <div class="container">
    <div class="row q-pt-sm q-pb-sm justify-between items-center">
      <div>
        <FilterBadges
          v-if="tableRef?.columnFilter?.hasActiveFilters?.value"
          :filters="tableRef?.columnFilter?.activeFilters?.value || []"
          :columns="columns"
          @remove="(col) => tableRef?.columnFilter?.clearFilter(col)"
        />
      </div>
      <f-btn :label="$t('new')" icon="add" @click="addNew" />
    </div>
    <div class="full-width">
      <DocBitsTable
        ref="tableRef"
        :rows="display_data || []"
        :columns="columns"
        :loading="loading"
        row-key="id"
        table-id="email_template_table"
        :features="{
          sorting: true,
          clientSideSort: true,
          filtering: true,
          selection: false,
          bulkActions: false,
          rowActions: true,
          resizable: false,
          pagination: false,
          columnReorder: true,
          columnSettings: false,
          stickyFirstColumn: false,
          stickyLastColumn: true,
        }"
        :row-actions="rowActions"
        :column-order="columnOrder"
        no-data-label="no_record_found"
        table-class="email-template-table-height"
        flat-style
        @row-action="handleRowAction"
        @row-click="handleRowClick"
        @column-reorder="handleColumnReorder"
      >
        <!-- Name column -->
        <template #body-cell-name="{ row }">
          {{ row.name }}
        </template>

        <!-- Subject column -->
        <template #body-cell-subject="{ row }">
          {{ row.subject }}
        </template>

        <!-- Document type column -->
        <template #body-cell-doc_type="{ row }">
          {{ row.doc_type }}
        </template>

        <!-- Last modified by column -->
        <template #body-cell-last_modified_by="{ row }">
          {{ getUserName(row.last_modified_by) }}
        </template>

        <!-- Last modified column -->
        <template #body-cell-last_modified_at="{ row }">
          {{ row.last_modified_on ? formatDateAccordingToPreference(row.last_modified_on) : formatDateAccordingToPreference(row.created_on) }}
        </template>
      </DocBitsTable>
    </div>
  </div>

  <q-dialog v-model="confirmDelete" persistent>
    <q-card>
      <q-card-section
        class="row"
        style="justify-content: center; display: flex"
      >
        <q-avatar icon="warning" color="primary" text-color="white" />
      </q-card-section>

      <q-card-section class="row items-center">
        <span class="q-ml-sm">{{ $t('msg_delete') }}</span>
      </q-card-section>

      <q-card-actions align="right">
        <f-btn
          appearance="cancel"
          :label="$t('cancel')"
          v-close-popup
        />
        <f-btn
          :label="$t('delete')"
          v-close-popup
          @click="deleteTemplate"
        />
      </q-card-actions>
    </q-card>
  </q-dialog>

  <Loader />
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { defineComponent, ref, computed } from 'vue';
import { emailTemplateStore } from 'src/store/main';
import { storeToRefs } from 'pinia';
import { useSettingStore } from 'src/store/Settings/setting.store';
import cache from 'src/utils/cache';
import { CONSTANTS } from 'src/constants';
import { ApiExceptions } from 'src/exceptions/index';
import type { dynamicObj } from 'src/pages/assets';
import { emailTemplateService } from 'src/services';
import dateUtils from 'src/utils/date';
import { DocBitsTable, FilterBadges } from 'src/components/Table';
import Loader from 'src/components/Loader.vue';
import type {
  UnifiedTableColumn,
  RowActionItem,
  RowActionPayload,
} from 'src/components/Table';
import { useTranslate } from '@tolgee/vue';
import { useDropdownStore } from 'src/store/Dropdown/dropdown.store';

export default defineComponent({
  el: '#app',
  mixins: [dateUtils, cache],
  components: {
    DocBitsTable,
    FilterBadges,
    Loader,
  },
  mounted() {
    this.init();
    this.loadColumnOrder();
  },
  data() {
    return {
      confirmDelete: ref(false),
      templateId: ref(''),
    };
  },
  setup() {
    const { t } = useTranslate();
    const email_template = emailTemplateStore();
    const { loading, display_data } = storeToRefs(email_template);
    const { getGeneralEmailTemplateData } = email_template;

    const setting_store = useSettingStore();
    const { datePattern } = setting_store;

    // Users dropdown for resolving user names
    const dropdownStore = useDropdownStore();
    const { usersMap } = storeToRefs(dropdownStore);
    const { prepareUsersDropdown } = dropdownStore;

    // Column definitions for DocBitsTable
    const columns = computed<UnifiedTableColumn[]>(() => [
      {
        name: 'name',
        label: t.value('name'),
        field: 'name',
        sortable: true,
        align: 'left',
        style: 'width: 25%',
      },
      {
        name: 'subject',
        label: t.value('subject'),
        field: 'subject',
        sortable: true,
        align: 'left',
      },
      {
        name: 'doc_type',
        label: t.value('document_type'),
        field: 'doc_type',
        sortable: true,
        align: 'left',
      },
      {
        name: 'last_modified_by',
        label: t.value('last_modified_by'),
        field: 'last_modified_by',
        sortable: true,
        align: 'left',
        style: 'width: 150px',
        filter: false,
      },
      {
        name: 'last_modified_at',
        label: t.value('last_modified_at'),
        field: (row: any) => row.last_modified_on || row.created_on,
        sortable: true,
        align: 'left',
        style: 'width: 150px',
        filter: false,
      },
    ]);

    // Row actions for edit and delete
    const rowActions: RowActionItem[] = [
      {
        key: 'edit',
        label: 'edit',
        icon: 'edit',
        color: 'primary',
      },
      {
        key: 'delete',
        label: 'delete',
        icon: 'delete',
        color: 'negative',
        separator: true,
      },
    ];

    // Template ref to access table's filter state
    const tableRef = ref<InstanceType<typeof DocBitsTable> | null>(null);

    return {
      loading,
      display_data,
      getGeneralEmailTemplateData,
      datePattern,
      columns,
      rowActions,
      columnOrder: ref<string[]>([]),
      tableRef,
      usersMap,
      prepareUsersDropdown,
      t,
    };
  },
  methods: {
    async init() {
      await this.prepareUsersDropdown();
      await this.getEmailData();
    },
    async getEmailData() {
      try {
        this.loading = true;
        await this.getGeneralEmailTemplateData();
      } catch (err: any) {
        logError(err);
      } finally {
        this.loading = false;
      }
    },
    loadColumnOrder() {
      const savedOrder = this.getDataByKey(
        CONSTANTS.email_template_columns_order,
      ) as string;
      if (savedOrder) {
        this.columnOrder = JSON.parse(savedOrder);
      }
    },
    handleColumnReorder(newOrder: string[]) {
      this.columnOrder = newOrder;
      this.setDataToLocalStorage(
        CONSTANTS.email_template_columns_order,
        JSON.stringify(newOrder),
      );
    },
    handleRowAction(payload: RowActionPayload) {
      const row = payload.row;
      if (payload.action === 'edit') {
        this.editTemplate(row.id);
      } else if (payload.action === 'delete') {
        this.confirmDialog(row.id);
      }
    },
    handleRowClick(payload: { row: any }) {
      this.editTemplate(payload.row.id);
    },
    addNew() {
      this.$router.push('/settings/email-templates/add');
    },
    editTemplate(id: string) {
      this.$router.push(`/settings/email-templates/${id}`);
    },
    confirmDialog(id: string) {
      this.templateId = id;
      this.confirmDelete = true;
    },
    async deleteTemplate() {
      try {
        this.loading = true;
        if (!this.templateId) {
          notify.error(this.$t('email_template_not_found'));
          return;
        }
        const response = await emailTemplateService.delete(this.templateId);
        if (!response || response.success === false) {
          throw response;
        }
        await this.getEmailData();
        notify.success(this.$t('email_template_deleted_success'));
        this.confirmDelete = false;
      } catch (error: any) {
        const msg = ApiExceptions.getErrorMessage(error as dynamicObj);
        notify.error(msg);
        logError(error);
      } finally {
        this.loading = false;
      }
    },
    getUserName(userId: string): string {
      if (!userId) return '-';
      const user = this.usersMap.get(Number(userId));
      if (user) {
        return `${user.first_name} ${user.last_name}`;
      }
      return userId;
    },
  },
});
</script>

<style lang="scss" scoped>
:deep(.email-template-table-height) {
  height: calc(100vh - 160px) !important;
}
</style>
